{"tool": "writeProjectFile", "params": {"content": "const fs = require('fs');
const v8 = require('v8');

console.log('--- Molly Diagnostic Capture Initiated ---');
try {
  const snapshot = v8.getHeapStatistics();
  fs.writeFileSync('diagnostic-dump.json', JSON.stringify({ 
    timestamp: new Date().toISOString(), 
    ...snapshot, 
    memoryUsage: process.memoryUsage() 
  }, null, 2));
  console.log('Diagnostic snapshot saved to diagnostic-dump.json');
} catch (e) {
  console.error('Diagnostic failed:', e);
}
process.exit(1);", "path": "scripts/diagnostic-capture.mjs"}}
